/// Look up an enum table by name.
pub fn enum_table(name: &str) -> Option<&'static [&'static str]> {
    match name {
        "syu_" => Some(ENUM_SYU_),
        "syu2_" => Some(ENUM_SYU2_),
        "san_" => Some(ENUM_SAN_),
        "icn_" => Some(ENUM_ICN_),
        "mons_" => Some(ENUM_MONS_),
        "mint_" => Some(ENUM_MINT_),
        "item_" => Some(ENUM_ITEM_),
        "ran1_" => Some(ENUM_RAN1_),
        "ran2_" => Some(ENUM_RAN2_),
        "ran3_" => Some(ENUM_RAN3_),
        "ran4_" => Some(ENUM_RAN4_),
        "syo_" => Some(ENUM_SYO_),
        "t0_" => Some(ENUM_T0_),
        "map_" => Some(ENUM_MAP_),
        "level_" => Some(ENUM_LEVEL_),
        _ => None,
    }
}

/// Read a little endian unsigned value of the given kind.
pub fn read_u32(raw: &[u8], off: usize, kind: FieldKind) -> Option<u32> {
    let n = match kind {
        FieldKind::U8 | FieldKind::I8 => 1usize,
        FieldKind::U16 | FieldKind::I16 => 2,
        FieldKind::U32 | FieldKind::I32 | FieldKind::F32 => 4,
        FieldKind::Bytes => return None,
    };
    if off + n > raw.len() {
        return None;
    }
    let mut v = 0u32;
    for i in 0..n {
        v |= (raw[off + i] as u32) << (8 * i);
    }
    Some(v)
}

/// Write a little endian unsigned value of the given kind.
pub fn write_u32(raw: &mut [u8], off: usize, kind: FieldKind, value: u32) -> bool {
    let n = match kind {
        FieldKind::U8 | FieldKind::I8 => 1usize,
        FieldKind::U16 | FieldKind::I16 => 2,
        FieldKind::U32 | FieldKind::I32 | FieldKind::F32 => 4,
        FieldKind::Bytes => return false,
    };
    if off + n > raw.len() {
        return false;
    }
    for i in 0..n {
        raw[off + i] = ((value >> (8 * i)) & 0xFF) as u8;
    }
    true
}